// hand: change the definitions, then generate again.

/** Any value that can be written as JSON. */
export type Json = null | boolean | number | string | Json[] | { [key: string]: Json };

/**
 * One row of a status item's card: a name and what it is.
 */
export interface CardRow {
  label: string;
  value: string;
}

export interface CommandExecute {
  args?: Json;
  /**
   * The command's id: one of the application's, or one of the plugin's own by its
   * name.
   */
  id: string;
}

export interface ContextSet {
  /**
   * The name of a condition the plugin's keys and menus can be shown under, as
   * `plugin:<id>.<key>`.
   */
  key: string;
  value: boolean;
}

/**
 * The kinds of failure a call can have.
 */
export type ErrorCode =
  /**
   * The plugin has no permission for it.
   */
  | "denied"
  /**
   * What was sent is not what the call takes.
   */
  | "invalid"
  /**
   * What was asked for is not there.
   */
  | "not_found"
  /**
   * The plugin is making more calls than it may at once.
   */
  | "busy"
  /**
   * It could not be done.
   */
  | "failed"
  /**
   * The plugin was stopped before it was done.
   */
  | "stopped"
  /**
   * The command was not handled by the plugin's code.
   */
  | "unhandled";

export interface KvKey {
  key: string;
}

export interface KvSet {
  key: string;
  value: Json;
}

/**
 * Nothing: what a call that takes no arguments is sent.
 */
export type Nothing = Record<string, never>;

/**
 * Something a session reported, as a plugin hears it.
 */
export interface SessionReport {
  /**
   * What was reported, as the session reported it.
   */
  details: Json;
  /**
   * The kind of report: `title`, `cwd`, `bell`, `command_started`,
   * `command_finished`, `program_status`, `foreground`, `activity`,
   * `disconnected`, `state` or `exit`.
   */
  kind: string;
  /**
   * The pane that shows it, if one does.
   */
  pane?: string;
  /**
   * The session.
   */
  session: string;
}

export interface SettingsGet {
  /**
   * One setting, by its key; all of the plugin's if left out.
   */
  key?: string;
}

export interface StatusClear {
  id: string;
  pane?: string;
}

export interface StatusSet {
  /**
   * The status item, by the name the manifest gives it.
   */
  id: string;
  /**
   * The pane whose header shows it, for an item in a pane's header.
   */
  pane?: string;
  value: StatusValue;
}

/**
 * What a status item shows. Each field left out keeps what the item showed before;
 * the manifest says what kind of item it is.
 */
export interface StatusValue {
  /**
   * The rows of the card shown when the pointer rests on the item.
   */
  card?: CardRow[];
  /**
   * Whether the item is out of sight for now.
   */
  hidden?: boolean;
  /**
   * What the item stands for, read out and shown beside a meter.
   */
  label?: string;
  /**
   * A sparkline's values, from the oldest to the newest.
   */
  points?: number[];
  /**
   * The words of a text or badge item, or the amount written out beside a meter or
   * a sparkline.
   */
  text?: string;
  tone?: Tone;
  /**
   * What the pointer is told when it rests on the item.
   */
  tooltip?: string;
  /**
   * How full a meter is, from 0 to 1.
   */
  value?: number;
}

export interface Subscribe {
  topic: Topic;
}

/**
 * What a status item's colour says.
 */
export type Tone = "neutral" | "info" | "success" | "warning" | "danger";

/**
 * What the plugin can hear about.
 */
export type Topic =
  /**
   * What sessions report: titles, directories, commands that start and end.
   */
  | "session";

/** Something that can be undone, such as listening. */
export interface Disposable {
  dispose(): void;
}

/** A call that failed, with the kind of failure in `code`. */
export declare class LumeError extends Error {
  readonly code: ErrorCode;
}

/** What the plugin is: the id it is installed under, which may not be its manifest's. */
export interface PluginSelf {
  readonly id: string;
  readonly manifestId: string;
  readonly name: string;
  readonly version: string;
}

/** The parts of the API that are not plain calls. */
export interface LumeBase {
  readonly self: PluginSelf;
  readonly commands: {
    /**
     * Carries out one of the plugin's commands, by the name its manifest gives it. The
     * handler is given the command's arguments, or null. Register handlers when the
     * plugin's code starts, before it waits for anything.
     */
    register(name: string, handler: (args: Json) => unknown): Disposable;
  };
  /** Timers. Each call of a timer's function counts against the plugin's time budget. */
  readonly timers: {
    setTimeout(fn: (...args: unknown[]) => void, ms?: number, ...args: unknown[]): number;
    setInterval(fn: (...args: unknown[]) => void, ms?: number, ...args: unknown[]): number;
    clearTimeout(id: number): void;
    clearInterval(id: number): void;
  };
  readonly sessions: {
    /** Hears what sessions report. Needs the `workspace.read` permission. */
    onEvent(listener: (report: SessionReport) => void): Disposable;
  };
  readonly settings: {
    /** Hears when the plugin's settings change; the listener is given all of them. */
    onChange(listener: (settings: Record<string, Json>) => void): Disposable;
  };
  /** Writes to the plugin's log, which `lume plugin logs <id>` shows. */
  readonly log: {
    debug(...values: unknown[]): void;
    info(...values: unknown[]): void;
    warn(...values: unknown[]): void;
    error(...values: unknown[]): void;
  };
  /** Calls `fn` when the plugin's code is about to be stopped. */
  onDeactivate(fn: () => void): void;
  readonly LumeError: typeof LumeError;
}

/** The calls of the API, by namespace. */
export interface LumeCalls {
  readonly commands: {
    /**
     * Runs a command: one of the plugin's own, by its name, or one of the
     *  application's that plugins may run. Its arguments are a JSON object.
     */
    execute(id: string, args?: Json): Promise<void>;
  };
  readonly context: {
    /**
     * Sets a condition the plugin's keys and menu items can be shown under.
     */
    set(key: string, value: boolean): Promise<void>;
  };
  readonly kv: {
    /**
     * The value the plugin stored under a key, or null.
     */
    get(key: string): Promise<Json>;
    /**
     * Stores a value under a key. What a plugin stores is its own, and all of it
     *  together may be 1 MiB.
     */
    set(key: string, value: Json): Promise<void>;
    /**
     * Removes what is stored under a key.
     */
    delete(key: string): Promise<void>;
    /**
     * The keys the plugin has stored values under.
     */
    list(): Promise<string[]>;
  };
  readonly settings: {
    /**
     * One of the plugin's settings, by its key, or all of them as an object when no
     *  key is given. A setting the user has not set has its default.
     */
    get(key?: string): Promise<Json>;
  };
  readonly status: {
    /**
     * Shows something in one of the plugin's status items. Fields left out keep what
     *  the item showed before.
     */
    set(id: string, value: StatusValue, pane?: string): Promise<void>;
    /**
     * Takes back what a status item showed, so it shows what its manifest says.
     */
    clear(id: string, pane?: string): Promise<void>;
  };
}

/** The whole API. */
export type Lume = LumeBase & LumeCalls;

declare global {
  const lume: Lume;
  const console: {
    log(...values: unknown[]): void;
    info(...values: unknown[]): void;
    debug(...values: unknown[]): void;
    warn(...values: unknown[]): void;
    error(...values: unknown[]): void;
  };
}
